questionvariables.text:
/*Identifying sets*/
/*model answer*/
ta_1:random_permutation([["Set a={A,B,C,D}",true],["Set B={1,2,3,4,5}",false],["Set C={a,b,c,d}",false]]);

correct_answer:rand_selection([
[1, true, "Set a={A,B,C,D}"],
[2, true, "Set B=1,2,3,4"],
[3, true, "Set D=(1,2,3,4)"],
[4, true, "Set E=[4,5,6,7]"],
[5, true, "Set A={a b c d}"]],1);
incorrect_answers:rand_selection([
[6, false, "Set B={1,2,3,4,5}"],
[7, false, "Set C={a,b,c,d}"],
[8, false, "Set D={}"]], 3);
ta: random_permutation(append(correct_answer,incorrect_answers));

ta_index: sort(makelist(x[1], x, ta));
ta_largest: last(ta_index);
